def main():
    slug = sys.argv[1]
    if slug not in REVIEWS:
        print("unknown slug", slug); sys.exit(2)
    path = "src/data/reviews.json"
    d = json.load(open(path))
    slugs = {r.get("slug") for r in d}
    if slug in slugs:
        print("SLUG ALREADY EXISTS, aborting"); sys.exit(3)
    d.append(REVIEWS[slug])
    json.dump(d, open(path, "w"), ensure_ascii=False, indent=1)
    print("appended", slug, "| total now", len(d))

if __name__ == "__main__":
    main()
